// Parse a TCP port from a string.
function parsePort(text) {
  // Reject anything that is not a plain number: blank input, junk like 'abc',
  // partial numbers like '80x', and non-primitives that coerce oddly.
  if (typeof text === 'number') {
    if (!Number.isInteger(text)) {
      throw new TypeError(`Port must be an integer, got ${text}`);
    }
  } else if (typeof text === 'string' && text.trim() !== '' && Number.isFinite(Number(text))) {
    if (!Number.isInteger(Number(text))) {
      throw new TypeError(`Port must be an integer, got '${text}'`);
    }
  } else {
    throw new TypeError(`Port must be a number, got ${JSON.stringify(text)}`);
  }

  var port = Number(text);
  if (port < 0 || port > 65535) {
    throw new RangeError(`Port must be between 0 and 65535, got ${port}`);
  }
  return port;
}
module.exports = { parsePort };

