// Parse a TCP port from a string. Throws on non-numeric input and on
// ports outside the valid range 0-65535.
function parsePort(text) {
  const raw = typeof text === 'string' ? text.trim() : text;
  if (typeof raw !== 'string' && typeof raw !== 'number') {
    throw new TypeError(`Invalid port: ${JSON.stringify(text)}`);
  }
  if (raw === '') {
    throw new TypeError('Invalid port: empty input');
  }
  const port = Number(raw);
  if (!Number.isInteger(port)) {
    throw new TypeError(`Invalid port: ${JSON.stringify(text)}`);
  }
  if (port < 0) {
    throw new RangeError(`Port out of range: ${port}`);
  }
  if (port > 65535) {
    throw new RangeError(`Port out of range: ${port}`);
  }
  return port;
}
module.exports = { parsePort };

